using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Imaging;using PdfSharp.Drawing;
internal static class TextSelectionAcceptance {
 [STAThread]static int Main(string[] args){try{string folder=Path.GetFullPath(Path.Combine("work","text-ocr-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(folder);
 string raster=Path.Combine(folder,"scan.pdf");using(var bitmap=new Bitmap(1200,1500))using(var g=Graphics.FromImage(bitmap))using(var font=new Font("Arial",45)){g.Clear(Color.White);g.DrawString("PDF Reader automatic OCR",font,Brushes.Black,80,200);g.DrawString("Select and copy this text",font,Brushes.Black,80,320);using(var stream=new MemoryStream()){bitmap.Save(stream,ImageFormat.Png);stream.Position=0;using(var pdf=new PdfSharp.Pdf.PdfDocument()){var page=pdf.AddPage();page.Width=PdfSharp.Drawing.XUnit.FromPoint(600);page.Height=PdfSharp.Drawing.XUnit.FromPoint(750);using(var canvas=XGraphics.FromPdfPage(page))using(var image=XImage.FromStream(stream))canvas.DrawImage(image,0,0,600,750);pdf.Save(raster);}}}
 using(var source=new PdfTextRegions(raster)){var result=(SelectableText)source.GetSelectableText(0);Console.WriteLine("SCAN source="+result.source+" words="+result.words.Length+" error="+result.error);if(result.source!="ocr"||!result.words.Any(w=>w.text.IndexOf("Reader",StringComparison.OrdinalIgnoreCase)>=0))throw new Exception("Raster page OCR failed");if(result.words.Any(w=>w.x<0||w.y<0||w.x+w.width>1.01||w.y+w.height>1.01))throw new Exception("OCR geometry out of page");}
 if(args.Length>0)using(var source=new PdfTextRegions(args[0]))foreach(int index in new[]{0,1,5,10,20}){var result=(SelectableText)source.GetSelectableText(index);Console.WriteLine("PAGE "+index+" source="+result.source+" words="+result.words.Length+" error="+result.error);if(index>=5&&result.words.Length==0)throw new Exception("Actual PDF body text unavailable");}
 Console.WriteLine("TEXT_OCR_ACCEPTANCE_PASS "+folder);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
